static bool Bridge_AccumulateCellBBox(D2GfxDataStrc* pGfxData, RECT* pAccum, bool bHasAny)
{
    if (!D2CMP_CelGetHandle(pGfxData) || !pGfxData->pCurrentCell)
        return bHasAny;
    D2GfxCellStrc* pCell = pGfxData->pCurrentCell;
    int32_t left   = pCell->nXOffset;
    int32_t bottom = pCell->nYOffset;
    int32_t right  = left + (int32_t)pCell->dwWidth - 1;
    int32_t top    = bottom - (int32_t)pCell->dwHeight + 1;
    if (!bHasAny)
    {
        pAccum->left   = left;
        pAccum->top    = top;
        pAccum->right  = right;
        pAccum->bottom = bottom;
    }
    else
    {
        if (left   < pAccum->left)   pAccum->left   = left;
        if (top    < pAccum->top)    pAccum->top    = top;
        if (right  > pAccum->right)  pAccum->right  = right;
        if (bottom > pAccum->bottom) pAccum->bottom = bottom;
    }
    return true;
}

static bool Bridge_HitTestSingleCell(D2GfxDataStrc* pGfxData, int32_t nLocalX, int32_t nLocalY)
{
    if (!D2CMP_CelGetHandle(pGfxData) || !pGfxData->pCurrentCell)
        return false;
    D2GfxCellStrc* pCell = pGfxData->pCurrentCell;
    int32_t w = (int32_t)pCell->dwWidth;
    int32_t h = (int32_t)pCell->dwHeight;
    if (w <= 0 || h <= 0)
        return false;
    int32_t relX = nLocalX - pCell->nXOffset;
    int32_t relY = nLocalY - (pCell->nYOffset - h + 1);
    if (relX < 0 || relX >= w || relY < 0 || relY >= h)
        return false;

    // Decode DC6 RLE scanlines if raw pixel data is available after header
    const uint8_t* pRaw = (const uint8_t*)pCell + 0x20;
    uint32_t dwLen = pCell->dwLength;
    if (dwLen == 0 || dwLen > 0x400000)
        return true;

    int32_t curX = 0;
    int32_t curY = (pCell->bFlip & 1) ? 0 : (h - 1);
    int32_t stepY = (pCell->bFlip & 1) ? 1 : -1;
    uint32_t pos = 0;
    while (pos < dwLen && curY >= 0 && curY < h)
    {
        uint8_t b = pRaw[pos++];
        if (b == 0x80)
        {
            curX = 0;
            curY += stepY;
        }
        else if (b & 0x80)
        {
            curX += (b & 0x7F);
        }
        else
        {
            int32_t run = (int32_t)b;
            if (curY == relY && relX >= curX && relX < curX + run)
                return true;
            curX += run;
            pos += (uint32_t)run;
        }
    }
    return false;
}

