int32_t __stdcall Bridge_D2CMP_CelHitTestPixel(void* pCelContext, int32_t nLocalX, int32_t nLocalY, int32_t bStrictAlpha)
{
    (void)bStrictAlpha;
    if (!pCelContext)
        return 0;
    D2UnitStrc* pUnit = (D2UnitStrc*)pCelContext;
    if (pUnit->dwUnitType <= UNIT_OBJECT)
    {
        D2CofRecordStrc* pCof = GFX_GetUnitActiveCofRecord(pUnit);
        if (pCof && pCof->nLayers > 0 && pCof->pLayers)
        {
            int nEngineDir = (pUnit->pDynamicPath && (pUnit->dwUnitType <= UNIT_MONSTER || pUnit->dwUnitType == UNIT_MISSILE)) ? PATH_GetDirection(pUnit->pDynamicPath) : 0;
            int nCofDir = GFXUTIL_EngineDirToCofDir(nEngineDir, pCof->nDirections);
            int nFrame = (pCof->nFramesPerDir > 0) ? (((uint32_t)pUnit->nSeqCurrentFramePrecise >> 8) % pCof->nFramesPerDir) : 0;
            for (uint8_t i = 0; i < pCof->nLayers; ++i)
            {
                const D2CofLayerStrc& layer = pCof->pLayers[i];
                D2GfxDataStrc tGfx = {};
                if (GFX_SetupUnitComponentGfxData(pUnit, &tGfx, layer.nComponent, nCofDir, nFrame, layer.szWeaponClass, 0, 0))
                {
                    if (Bridge_HitTestSingleCell(&tGfx, nLocalX, nLocalY))
                        return 1;
                }
            }
            return (nLocalX >= pCof->nXMin && nLocalX <= pCof->nXMax && nLocalY >= pCof->nYMin && nLocalY <= pCof->nYMax) ? 1 : 0;
        }
    }
    else
    {
        D2GfxDataStrc tGfx = {};
        if (GFX_ValidateUnitGfxData(pUnit, &tGfx))
            return Bridge_HitTestSingleCell(&tGfx, nLocalX, nLocalY) ? 1 : 0;
    }
    return 1;
}
